            Json(json!({"detail":"candidate side effects are not public yet"})),
        )
            .into_response();
    }
    if req.text.trim().is_empty() {
        return (
            axum::http::StatusCode::BAD_REQUEST,
            Json(json!({"detail":"text must not be empty"})),
        )
            .into_response();
    }
