const DELIVERY_QUEUE: usize = 256;

#[derive(Clone)]
struct DeliveryState {
    next_epoch: Arc<AtomicU64>,
    next_sequence: Arc<AtomicU64>,
    connections: Arc<Mutex<HashMap<u64, mpsc::Sender<DeliveryFrame>>>>,
}

enum DeliveryFrame {
    Event { sequence: u64, event: Event },
    Message(Message),
}

struct DeliveryConnection {
    epoch: u64,
    receiver: mpsc::Receiver<DeliveryFrame>,
}

impl DeliveryState {
    fn new() -> Self {
        Self {
            next_epoch: Arc::new(AtomicU64::new(1)),
            next_sequence: Arc::new(AtomicU64::new(0)),
            connections: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn register(&self) -> DeliveryConnection {
        let epoch = self.next_epoch.fetch_add(1, Ordering::Relaxed);
        let (sender, receiver) = mpsc::channel(DELIVERY_QUEUE);
        self.connections.lock().await.insert(epoch, sender);
        DeliveryConnection { epoch, receiver }
    }

    async fn retire(&self, epoch: u64) {
        self.connections.lock().await.remove(&epoch);
    }

    async fn publish(&self, event: Event) {
        let sequence = self.next_sequence.fetch_add(1, Ordering::Relaxed);
        let mut dead = Vec::new();
        let connections = self.connections.lock().await;
        for (&epoch, sender) in connections.iter() {
            if sender.try_send(DeliveryFrame::Event { sequence, event: event.clone() }).is_err() {
                dead.push(epoch);
            }
        }
        drop(connections);
        if !dead.is_empty() {
            let mut connections = self.connections.lock().await;
            for epoch in dead {
                connections.remove(&epoch);
            }
        }
    }

    async fn send(&self, epoch: u64, message: Message) -> bool {
        self.connections
            .lock()
            .await
            .get(&epoch)
            .is_some_and(|sender| sender.try_send(DeliveryFrame::Message(message)).is_ok())
    }

    async fn connected(&self) -> bool {
        !self.connections.lock().await.is_empty()
    }
}

