            text,
            generation,
            sequence,
        } = request;
        state.0.coordinator.touch_activity();
        let started = std::time::Instant::now();
        match state.0.speaker.synthesize(&text).await {
            Ok(audio) => {
                tracing::info!(
                    chars = text.chars().count(),
                    bytes = audio.len(),
                    elapsed = ?started.elapsed(),
