fn duration_value(values: &HashMap<String, String>, name: &str, default_ms: u64) -> Duration {
    let parsed = values.get(name).and_then(|value| value.trim().parse::<u64>().ok());
    Duration::from_millis(parsed.filter(|value| (1..=SPEECH_DEADLINE_MAX_MS).contains(value)).unwrap_or(default_ms))
}

