    pub async fn synthesize_until(
        &self,
        text: &str,
        deadline: Instant,
    ) -> Result<Vec<u8>, AudioError> {
        if !self.configured() {
            return Err(AudioError::Tts("ELEVENLABS_API_KEY is not set".into()));
        }
        #[derive(Serialize)]
        struct Settings {
            stability: f32,
            similarity_boost: f32,
            style: f32,
            speed: f32,
        }
