    socket: &mut futures_util::stream::SplitSink<WebSocket, Message>,
    event: Event,
) -> Result<(), axum::Error> {
    match event {
        Event::Json(value) => socket.send(Message::Text(value.to_string().into())).await,
        Event::Audio {
            audio,
            generation,
            sequence,
        } => {
            socket
                .send(Message::Text(
                    json!({"type":"audio", "generation":generation, "sequence":sequence})
                        .to_string()
                        .into(),
                ))
                .await?;
            socket.send(Message::Binary(audio.into())).await
        }
    }
}

